// It then adds the pod to the addedPods map and registers the services
// associated with the containers in the pod to Etcd.
// Finally, it updates the metrics and returns nil.
func (c *Controller) eventAddFunc(podInfo *PodInfo, adapterV2 etcd.AdapterV2Interface, verifyInNCatalogs bool, catalogs []*sync.Map, lrcConfig *nexusmeshv1alpha1.LocalRegistrationConfig) error {
	log.Debug().Dict("custom_attributes", logger.Attrs().
		Str("pod_name", podInfo.Name).
		Str("pod_ip", podInfo.IP).
		Str("namespace", podInfo.Namespace).
		Str("phase", string(podInfo.Phase)).
		Str("ready", string(podInfo.Ready))).
		Msg("eventAddFunc")
	svcs := getServiceNameFromPod(podInfo, *c.k8sServices.Load(), lrcConfig)
	var multiErr error = nil
	if podInfo.Phase == core.PodRunning && podInfo.Ready == core.ConditionTrue {
		filterPort := podInfo.annotatedPortToFilterOn(lrcConfig)
		for _, container := range podInfo.ContainerStatuses {

			if container.Name == utils.EnvoyContainerName || container.Name == utils.NexusEnvoyContainerName || container.Name == utils.DbDriverContainerName {
				continue
			}

			// The service-ports annotation is pod-level but registration is
			// per-container. Without this, a sidecar that never listens on the
			// annotated port still gets its own etcd endpoint keyed on it.
			if filterPort != 0 && !podInfo.declaresPort(container.Name, filterPort) {
				log.Debug().Dict("custom_attributes", logger.Attrs().
					Str("pod_name", podInfo.Name).
					Str("pod_ip", podInfo.IP).
					Str("container", container.Name).
					Int("annotatedPort", filterPort)).
					Msg("container does not declare the annotated service port; skipping registration")
				continue
			}

			endpointList, err := podInfo.PodToEtcdServiceEndpoint(container, svcs, servicev1.HealthCheckStatus_HEALTHY, lrcConfig)
			if err != nil {
				multiErr = multierr.Append(multiErr, err)
				log.Error().Dict("custom_attributes", logger.Attrs().
					Str("status_code", string(logger.GALACTUS_POD_CONVERT_FAILED)).
					Str("pod_name", podInfo.Name).
					Str("pod_ip", podInfo.IP).
					Str("error", err.Error())).
					Msg(logger.Msg(logger.GALACTUS_POD_CONVERT_FAILED))
				metrics.UpdatePodRegisterStatus(podInfo.Namespace, podInfo.Name, strings.Join(svcs, ","), metrics.PodRegisterStatusEndpointConversionFailed)
				continue
			}

			// Flow-1 traceability (LOG-10): the endpoint(s) were built for this
			// container — the build hop that precedes the etcd write.
			log.Info().Dict("custom_attributes", logger.Attrs().
				Str("status_code", string(logger.GALACTUS_ENDPOINT_BUILT)).
				Str("pod_name", podInfo.Name).
				Str("pod_ip", podInfo.IP).
				Str("container", container.Name).
				Int("endpoints", len(endpointList))).
				Msg(logger.Msg(logger.GALACTUS_ENDPOINT_BUILT))

			for _, endpoint := range endpointList {
				serviceID, err := toServiceID(endpoint)
				if err != nil {
					multiErr = multierr.Append(multiErr, err)
					log.Error().Dict("custom_attributes", logger.Attrs().
						Str("status_code", string(logger.GALACTUS_POD_SERVICEID_FAILED)).
						Str("pod_name", podInfo.Name).
						Str("pod_ip", podInfo.IP).
						Str("error", err.Error())).
						Msg(logger.Msg(logger.GALACTUS_POD_SERVICEID_FAILED))
					metrics.UpdatePodRegisterStatus(podInfo.Namespace, podInfo.Name, strings.Join(svcs, ","), metrics.PodRegisterStatusEndpointConversionFailed)
					continue
				}
				currentVersion := endpoint.Version.GetValue()
				endpointKey := adapterV2.GetEndpointKey(endpoint)
				if addedInfo, found := c.addedPods.Load(serviceID); found {
					infos, ok := addedInfo.([]EndpointInfo)
					if !ok {
						infos = nil
					}
					// Check if this specific endpoint key is already registered with the same version
					alreadyRegistered := false
					for _, info := range infos {
						if info.EndpointKey == endpointKey && currentVersion == info.Version {
							alreadyRegistered = true
							break
						}
					}
					if alreadyRegistered {
						metrics.UpdatePodRegisterStatus(podInfo.Namespace, podInfo.Name, strings.Join(svcs, ","), metrics.PodRegisterStatusRegistered)
						// Should we check the catalogs for the service?
						if !verifyInNCatalogs {
							log.Debug().Msgf("No need to verify in catalogs, skipping: %s", endpointKey)
							continue
						}

						// Check the catalogs for the service

						// Check the primary catalog for the service
						if storedVersion, found := catalogs[0].Load(endpointKey); found && storedVersion.(string) != "" {
							// Found the service in primary catalog, now check if the service is multi-entity enabled
							serviceName := endpoint.Service.GetValue()
							_, ok := c.adapterPrimary.GetMultiEntityServices().Load(serviceName)
							if ok {
								// Service is multi-entity enabled, now check if the service is in the secondary catalog
								if storeMultiEntityVersion, found := catalogs[1].Load(endpointKey); found && storeMultiEntityVersion.(string) != "" {
									// Same version across, no need to register
									if storeMultiEntityVersion.(string) == currentVersion && storedVersion.(string) == currentVersion {
										log.Debug().Msgf("[Multi-entity] Same version across, no need to register: %s", endpointKey)
										continue
									} else {
										log.Debug().Msgf("[Multi-entity] Different version, storedMultiEntityVersion: %s, storedVersion: %s, currentVersion: %s, need to register: %s", storeMultiEntityVersion, storedVersion, currentVersion, endpointKey)
									}
								} else {
									log.Debug().Msgf("No version found in secondary catalog: %s", endpointKey)
								}
							} else {
								// Same version, no need to register
								if storedVersion.(string) == currentVersion {
									log.Debug().Msgf("Same version, no need to register: %s", endpointKey)
									continue
								} else {
									log.Debug().Msgf("Different version storedVersion: %s, currentVersion: %s, need to register: %s", storedVersion, currentVersion, endpointKey)
								}
							}
						} else {
							log.Debug().Msgf("No version found in catalog: %s", endpointKey)
						}
					}
				}

				if container.Ready {
					if checkMultiEntityAnnotationForPodInfo(podInfo) || checkUnifiedAnnotationForLRC(lrcConfig) {
						c.UpdateMultiEntityServices(svcs)
					} else {
						c.CleanMultiEntityServices(svcs)
					}
					// SYNC write-path guard (CAST spot-VM orphan fix, Change 2):
					// NEVER write an endpoint key whose IP is not in the pod's
					// current Status.PodIPs. During a transient informer state a
					// pod can briefly present a stale IP; writing it would create
					// exactly the orphan Branch B has to clean up, and would race
					// the delete/re-add. Fail-open only when PodIPs is empty
					// (older informer state) so existing behavior is preserved.
					if !podInfo.ipInCurrentPodIPs(endpoint.Address.GetValue()) {
						metrics.PodIPDriftTotal.WithLabelValues(endpoint.Service.GetValue()).Inc()
						log.Warn().Dict("custom_attributes", logger.Attrs().
							Str("status_code", string(logger.GALACTUS_POD_REGISTER_FAILED)).
							Str("pod_name", podInfo.Name).
							Str("pod_ip", podInfo.IP).
							Str("service", endpoint.Service.GetValue()).
							Str("serviceID", serviceID).
							Str("endpoint_address", endpoint.Address.GetValue()).
							Strs("pod_ips", podInfo.PodIPs)).
							Msg("SyncFunc: refusing to register endpoint whose IP is not in pod's current PodIPs")
						continue
					}
					// V4 migration: LRC endpoints write catalog to v4 path. Remove post-migration.
					endpointIsLRC := lrcConfig != nil && endpoint.Service.GetValue() == lrcConfig.Spec.AtlasApplicationName
					log.Debug().Msgf("[eventAddFunc] Registering service endpoint: %s (isLRC=%v)", endpoint.Id.GetValue(), endpointIsLRC)
					err = adapterV2.Register(endpoint, endpointIsLRC)
					metrics.SyncFuncSyncEndpointCounter.WithLabelValues("sync:register", strings.Join(svcs, ",")).Inc()
					if err != nil {
						multiErr = multierr.Append(multiErr, err)
						log.Error().Dict("custom_attributes", logger.Attrs().
							Str("status_code", string(logger.GALACTUS_POD_REGISTER_FAILED)).
							Str("pod_name", podInfo.Name).
							Str("pod_ip", podInfo.IP).
							Str("service", endpoint.Service.GetValue()).
							Str("serviceID", serviceID).
							Str("error", err.Error())).
							Msg(logger.Msg(logger.GALACTUS_POD_REGISTER_FAILED))
						metrics.UpdatePodRegisterStatus(podInfo.Namespace, podInfo.Name, strings.Join(svcs, ","), metrics.PodRegisterStatusEtcdCallFailed)
					} else {
						// Log successful registration with method and LRC details.
						// registrationMethod disambiguates dual-write entries:
						//   - "LRC"             : LRC-keyed entry (endpoint.Service == lrcConfig.AtlasApplicationName)
						//   - "ANNOTATION_DUAL" : annotation-keyed entry written via dual-write fall-through
						//                         (lrcConfig != nil but endpoint.Service != lrcSvc)
						//   - "ANNOTATION"      : pure annotation registration (no LRC match)
						attrs := logger.Attrs().
							Str("status_code", string(logger.GALACTUS_POD_REGISTERED)).
							Str("pod_name", podInfo.Name).
							Str("pod_ip", podInfo.IP).
							Str("namespace", podInfo.Namespace).
							Str("service", endpoint.Service.GetValue()).
							Str("serviceID", serviceID).
							Uint32("port", endpoint.Port.GetValue()).
							Str("address", endpoint.Address.GetValue()).
							Str("version", currentVersion)
						switch {
						case lrcConfig != nil && endpoint.Service.GetValue() == lrcConfig.Spec.AtlasApplicationName:
							attrs.
								Str("registrationMethod", "LRC").
								Str("lrcName", lrcConfig.Name).
								Str("lrcNamespace", lrcConfig.Namespace).
								Str("lrcResourceVersion", lrcConfig.ResourceVersion)
						case lrcConfig != nil:
							attrs.
								Str("registrationMethod", "ANNOTATION_DUAL").
								Str("lrcName", lrcConfig.Name).
								Str("lrcNamespace", lrcConfig.Namespace).
								Str("lrcResourceVersion", lrcConfig.ResourceVersion).
								Bool("dualRegistration", true)
						default:
							attrs.Str("registrationMethod", "ANNOTATION")
						}
						log.Info().Dict("custom_attributes", attrs).Msg(logger.Msg(logger.GALACTUS_POD_REGISTERED))
						superseded := c.upsertAddedPod(serviceID, EndpointInfo{
							Version:     currentVersion,
							EndpointKey: endpointKey,
							Namespace:   podInfo.Namespace,
						})
						if err := c.deregisterSupersededKeys(podInfo, adapterV2, serviceID, superseded); err != nil {
							multiErr = multierr.Append(multiErr, err)
						}
						metrics.UpdatePodRegisterStatus(podInfo.Namespace, podInfo.Name, strings.Join(svcs, ","), metrics.PodRegisterStatusRegistered)
					}
				} else {
					log.Warn().Dict("custom_attributes", logger.Attrs().
						Str("status_code", string(logger.GALACTUS_POD_CONTAINER_NOT_READY)).
						Str("pod_name", podInfo.Name).
						Str("pod_ip", podInfo.IP).
						Str("container", container.Name)).
						Msg("Container not ready, removing from catalog")
					metrics.UpdatePodRegisterStatus(podInfo.Namespace, podInfo.Name, strings.Join(svcs, ","), metrics.PodRegisterStatusNotReady)
				}
			}

		}

		// Clean stale addedPods entries for this pod if zero endpoints
		// were registered (e.g. all probes failed). This prevents ghost endpoints.
		registeredPorts := 0
		c.addedPods.Range(func(key, value any) bool {
			serviceID, ok := key.(string)
			if !ok {
				return true
			}
			infos, ok := value.([]EndpointInfo)
			if !ok {
				return true
			}
			for _, info := range infos {
				if info.Namespace == podInfo.Namespace && strings.Contains(serviceID, "/"+podInfo.Name+"/") {
					registeredPorts++
				}
			}
			return true
		})
		// If we attempted registration but got zero successes and there are stale entries, clean them
		if multiErr != nil && registeredPorts == 0 {
			c.addedPods.Range(func(key, value any) bool {
				serviceID, ok := key.(string)
				if !ok {
					return true
				}
				if !strings.Contains(serviceID, "/"+podInfo.Name+"/") {
					return true
				}
				infos, ok := value.([]EndpointInfo)
				if !ok {
					return true
				}
				for _, info := range infos {
					if info.Namespace == podInfo.Namespace {
						log.Warn().Dict("custom_attributes", logger.Attrs().
							Str("pod_name", podInfo.Name).
							Str("pod_ip", podInfo.IP).
							Str("serviceID", serviceID)).
							Msg("Cleaning stale addedPods entry: all probes failed during re-sync")
						c.addedPods.Delete(serviceID)
						c.addedPodsMu.Delete(serviceID)
						return true
					}
				}
				return true
			})
		}
		// Track partial registration: only relevant for LRC multi-port where
		// totalPorts (from the LRC spec) may exceed actually registered ports.
		if lrcConfig != nil && len(lrcConfig.Spec.Ports) > 0 {
			totalPorts := len(lrcConfig.Spec.Ports)
			if registeredPorts > 0 && totalPorts > registeredPorts {
				metrics.PartialRegistrationTotal.WithLabelValues(podInfo.Namespace, strings.Join(svcs, ",")).Inc()
			}
		}
	} else {
		// Flow-1 traceability (LOG-10): pod not Running/Ready — registration is
		// skipped. Queryable INFO with pod identity in structured fields (no
		// pod name baked into the message).
		for _, container := range podInfo.ContainerStatuses {
			log.Info().Dict("custom_attributes", logger.Attrs().
				Str("status_code", string(logger.GALACTUS_POD_SKIPPED_NOT_READY)).
				Str("pod_name", podInfo.Name).
				Str("pod_ip", podInfo.IP).
				Str("container", container.Name).
				Bool("container_ready", container.Ready).
				Str("phase", string(podInfo.Phase)).
				Str("ready", string(podInfo.Ready))).
				Msg(logger.Msg(logger.GALACTUS_POD_SKIPPED_NOT_READY))
		}
	}
	return multiErr
}

